def select_peer_for_learning(
    current_user_id,
    user_emotional_state,   # Used only for safety/accessibility boundaries,
                            # never to increase pressure or dependence
    peer_database,
    consent,
    learning_context
):
    """
    Select an anonymized benchmark profile for learning support.

    Strategies:
      - aspiration_target: slightly advanced, demonstrably attainable model
      - relatability_target: similar path, pace, or misconception pattern

    Returns an aggregate/anonymized profile, not an identifiable student.
    """

    if not consent.allows_peer_comparison:
        return {
            "strategy": "none",
            "profile": None,
            "message": "Peer comparison is disabled. Here's a personal-progress view instead."
        }

    # Never use emotional state to select a pressure-inducing comparison.
    # If the learner appears distressed, avoid comparison entirely.
    if emotional_state_requires_low_pressure_support(user_emotional_state):
