def trigger_emotional_intervention(user_id: str, 
                                   real_time_metrics: dict, 
                                   historical_data: dict) -> dict:
    """
    Determines the appropriate emotional micro-intervention based on
    real-time behavioral signals and the student's historical response patterns.

    Args:
        user_id: Unique identifier for the student.
        real_time_metrics: Dictionary with keys:
            - 'typing_speed' (float, chars per second)
            - 'voice_pitch' (float, Hz – optional, could be None)
            - 'sentiment_score' (float, -1.0 to 1.0, negative = frustrated)
        historical_data: Dictionary containing:
            - 'intervention_history': list of past intervention outcomes
              (each entry: {'type': str, 'success': bool, 'context': ...})
            - 'learning_state': e.g., 'current_topic_difficulty', 'mastery_level'

    Returns:
        dict with keys:
            - 'intervention_type': one of ['success_story', 'unstuck_prompt', 
                                           'challenge_switch', 'none']
            - 'parameters': dict (e.g., story_id, prompt_text, difficulty_adjustment)
    """

    # --- 1. Extract real-time signals ---
    typing_speed = real_time_metrics.get('typing_speed', None)
    voice_pitch = real_time_metrics.get('voice_pitch', None)
    sentiment = real_time_metrics.get('sentiment_score', 0.0)  # neutral default

    # --- 2. Heuristic thresholds (can be user-tuned per historical data) ---
    FRUSTRATION_SENTIMENT = -0.4          # negative sentiment indicates frustration
    BOREDOM_TYPING_SPEED_UPPER = 1.5      # slow typing may indicate boredom or confusion
    BOREDOM_TYPING_SPEED_LOWER = 0.5      # very slow typing often means stuck
    OVERCONFIDENCE_SENTIMENT = 0.6        # high positive sentiment with fast typing

    # --- 3. Determine base emotional state ---
    # Prioritize sentiment score; typing speed refines.
    if sentiment < FRUSTRATION_SENTIMENT:
        emotional_state = 'frustration'
    elif sentiment > OVERCONFIDENCE_SENTIMENT:
        emotional_state = 'overconfidence'
    else:
        # Use typing speed to differentiate boredom vs. neutral
        if typing_speed is not None:
            if typing_speed < BOREDOM_TYPING_SPEED_LOWER:
                emotional_state = 'stuck'      # (subtype of frustration)
            elif typing_speed < BOREDOM_TYPING_SPEED_UPPER:
                emotional_state = 'boredom'
            else:
                emotional_state = 'neutral'
        else:
            emotional_state = 'neutral'

    # --- 4. Incorporate historical response patterns ---
