    intervention_history = historical_data.get('intervention_history', [])
    success_counts = {'success_story': 0, 'unstuck_prompt': 0, 'challenge_switch': 0}
    total_counts = {'success_story': 0, 'unstuck_prompt': 0, 'challenge_switch': 0}

