        itype = entry.get('type')
        if itype in success_counts:
            total_counts[itype] += 1
            if entry.get('success', False):
                success_counts[itype] += 1

    def success_rate(itype):
        if total_counts[itype] == 0:
            return 0.5  # default equal probability
        return success_counts[itype] / total_counts[itype]

    # --- 5. Select intervention based on emotional state and best historical match ---
